import re, numpy as np

def get_grids(t):
    # extract grid blocks following "input (" and "output ("
    lines = t.split("\n")
    grids = []
    cur = []
    for ln in lines:
        if re.fullmatch(r"[\d ]+", ln.strip()) and ln.strip():
            cur.append([int(x) for x in ln.split()])
        else:
            if cur: grids.append(cur); cur=[]
    if cur: grids.append(cur)
    return grids

def comps(g):
    bg = g[0][0]
    R,C = len(g), len(g[0])
    seen = [[False]*C for _ in range(R)]
    out=[]
    from collections import deque
    for r in range(R):
        for c in range(C):
            if g[r][c]!=bg and not seen[r][c]:
                col=g[r][c]; cells=set(); dq=deque([(r,c)]); seen[r][c]=True
                while dq:
                    a,b=dq.popleft(); cells.add((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<R and 0<=nb<C and not seen[na][nb] and g[na][nb]==col:
                            seen[na][nb]=True; dq.append((na,nb))
                out.append((col,cells))
    return out

