from collections import Counter
def comps2(g):
    R,C=len(g),len(g[0])
    bg = Counter(x for row in g for x in row).most_common(1)[0][0]
    seen=[[False]*C for _ in range(R)]
    out=[]
    for r in range(R):
        for c in range(C):
            if g[r][c]!=bg and not seen[r][c]:
                col=g[r][c]; cells=set(); dq=deque([(r,c)]); seen[r][c]=True
                while dq:
                    a,b=dq.popleft(); cells.add((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<R and 0<=nb<C and not seen[na][nb] and g[na][nb]==col:
                            seen[na][nb]=True; dq.append((na,nb))
                out.append((col,cells))
    return out, bg

