def canon(cells):
    rs=[r for r,c in cells]; cs=[c for r,c in cells]
    mr,mc=min(rs),min(cs)
    cells={(r-mr,c-mc) for r,c in cells}
    best=None
    cur=cells
    for k in range(4):
        for cand in (cur, {(c,-r) for r,c in cur}):
            rs=[r for r,c in cand]; cs=[c for r,c in cand]
            mr,mc=min(rs),min(cs)
            norm=frozenset((r-mr,c-mc) for r,c in cand)
            key=tuple(sorted(norm))
            if best is None or key<best: best=key
        cur={(c,-r) for r,c in cur}  # rotate
    return best

